import{_ as a,c as t,o,ae as r}from"./chunks/framework.DEXG3EuZ.js";const h=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/architecture.md","filePath":"en/guide/architecture.md","lastUpdated":1792605191000}'),s={name:"en/guide/architecture.md"};function i(n,e,c,l,d,p){return o(),t("div",null,[...e[0]||(e[0]=[r(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>v2 makes directory boundaries explicit so contributors and coding agents do not have to guess where code belongs.</p><h2 id="layers" tabindex="-1">Layers <a class="header-anchor" href="#layers" aria-label="Permalink to &quot;Layers&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>views -&gt; components / composables -&gt; api modules / services -&gt; transport / types</span></span>
<span class="line"><span>main  -&gt; plugins / router / store</span></span>
<span class="line"><span>build -&gt; Vite plugins</span></span></code></pre></div><ul><li><code>src/api/client.ts</code> owns Axios, interceptors, response unwrapping, and <code>ApiError</code> only.</li><li><code>src/api/modules</code> declares domain endpoints without Toast, Router, or component behavior.</li><li><code>src/services</code> contains framework-independent providers, protocol parsers, and adapters.</li><li><code>src/composables</code> orchestrates Vue reactivity and lifecycle.</li><li><code>src/store</code> contains client state only; TanStack Query owns server state.</li><li><code>src/views</code> is the route composition layer; non-core pages are lazy-loaded.</li></ul><h2 id="router-decision" tabindex="-1">Router Decision <a class="header-anchor" href="#router-decision" aria-label="Permalink to &quot;Router Decision&quot;">​</a></h2><p>The project keeps an explicit router table. At the current scale, <code>RouteRecordRaw</code> is easier to review for permissions, layouts, titles, KeepAlive, and bundle boundaries. The old <code>vite-plugin-pages</code> integration was not restored. If page count eventually justifies file conventions, evaluate <code>unplugin-vue-router</code> as a complete typed-routes, meta, layout, and migration-testing change.</p><h2 id="build" tabindex="-1">Build <a class="header-anchor" href="#build" aria-label="Permalink to &quot;Build&quot;">​</a></h2><p>Vite 8 uses Rolldown. <code>VITE_UI_FRAMEWORK</code> selects one UI resolver and demo alias. AI Chat, Query examples, and secondary pages use dynamic imports. SVG sprites are always available; Sharp/SVGO, PWA, gzip, and bundle reports are feature flags.</p><h2 id="protected-constraints" tabindex="-1">Protected Constraints <a class="header-anchor" href="#protected-constraints" aria-label="Permalink to &quot;Protected Constraints&quot;">​</a></h2><ul><li>The request layer does not import UI or Router.</li><li>The Service Worker does not cache APIs by default.</li><li>Three UI libraries never enter the same production graph.</li><li>AI and Markdown output is sanitized.</li><li>pnpm is the only package manager.</li></ul>`,11)])])}const m=a(s,[["render",i]]);export{h as __pageData,m as default};
